            "footer.thankyou": "Gracias por {dwn} descargas.",
            "download-button": "Descargar",
            "localization-progress": "Esta página está traducida al {currentLocale} {localizationProgress}. ¡Para ayudar a traducir, haz clic [aquí]({url})!",
            "intro.tagline": "¡Haz Que Tu Ratón De $10 Sea Mejor Que Un Trackpad De Apple!",
            "intro.big-tagline": "¡Haz Que Tu Ratón De $10 Sea Mejor Que Un Trackpad De Apple!",
            "navbar.title": "Mac Mouse Fix",
            "navbar.links.overview": "Resumen",
            "navbar.links.github": "Más en GitHub",
            "feature-card.expand-button": "Véalo en Acción",
