            "intro.tagline": "Rendez votre souris à 10 $ meilleure qu'un trackpad Apple !",
            "intro.big-tagline": "Rendez votre souris à 10 $ meilleure qu'un trackpad Apple !",
            "navbar.title": "Mac Mouse Fix",
            "navbar.links.overview": "Aperçu",
            "navbar.links.github": "Plus d'informations sur GitHub",
