            "intro.tagline": "Spraw by twoja myszka była lepsza niż gładzik od Apple!",
            "intro.big-tagline": "Spraw by twoja myszka była lepsza niż gładzik od Apple!",
            "navbar.title": "Mac Mouse Fix",
            "navbar.links.overview": "Przegląd",
