            "localization-progress": "此页面已经{localizationProgress}翻译成{currentLocale}了，要帮忙翻译请点击[这里]({url})！",
            "intro.tagline": "让你10美元的鼠标比苹果触控板还好用！",
            "intro.big-tagline": "让你10美元的鼠标比苹果触控板还好用！",
            "navbar.title": "Mac Mouse Fix",
            "navbar.links.overview": "总览",
